arguments:
{"sql":"CREATE OR REPLACE FUNCTION transfer_parts(
    source_inventory_id INTEGER,
    target_inventory_id INTEGER,
    part_to_transfer_num VARCHAR,
    color_to_transfer_id INTEGER,
    quantity_to_transfer INTEGER,
    transfer_reason VARCHAR DEFAULT 'manual_transfer'
) RETURNS TEXT
LANGUAGE plpgsql
AS $$
DECLARE
    source_exists BOOLEAN;
    target_exists BOOLEAN;
    part_exists BOOLEAN;
    color_exists BOOLEAN;
    current_quantity INTEGER;
    error_msg TEXT := NULL;
    log_status VARCHAR := 'success';
    spare_quantity INTEGER := 0;
    regular_quantity INTEGER := 0;
BEGIN
    IF source_inventory_id = target_inventory_id THEN
        error_msg := 'Source and target inventories cannot be the same.';
        log_status := 'failed';
    END IF;
    IF quantity_to_transfer < 1 OR quantity_to_transfer > 500 THEN
        error_msg := 'Transfer quantity must be between 1 and 500.';
        log_status := 'failed';
    END IF;
    SELECT EXISTS(SELECT 1 FROM lego_inventories WHERE id = source_inventory_id) INTO source_exists;
    IF NOT source_exists THEN
        error_msg := 'Source inventory ID does not exist.';
        log_status := 'failed';
    END IF;
    SELECT EXISTS(SELECT 1 FROM lego_inventories WHERE id = target_inventory_id) INTO target_exists;
    IF NOT target_exists THEN
        error_msg := 'Target inventory ID does not exist.';
        log_status := 'failed';
    END IF;
    SELECT EXISTS(SELECT 1 FROM lego_parts WHERE part_num = part_to_transfer_num) INTO part_exists;
    IF NOT part_exists THEN
        error_msg := 'Part number does not exist.';
        log_status := 'failed';
    END IF;
    SELECT EXISTS(SELECT 1 FROM lego_colors WHERE id = color_to_transfer_id) INTO color_exists;
    IF NOT color_exists THEN
        error_msg := 'Color ID does not exist.';
        log_status := 'failed';
    END IF;
    IF error_msg IS NOT NULL THEN
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, log_status, error_msg
        );
        RETURN 'Failed: ' || error_msg;
    END IF;
    BEGIN
        PERFORM id FROM lego_inventories WHERE id IN (source_inventory_id, target_inventory_id) FOR UPDATE;
        SELECT COALESCE(SUM(quantity), 0) INTO current_quantity
        FROM lego_inventory_parts
        WHERE inventory_id = source_inventory_id
          AND part_num = part_to_transfer_num
          AND color_id = color_to_transfer_id
        FOR UPDATE;
        SELECT COALESCE(quantity, 0) INTO regular_quantity
        FROM lego_inventory_parts
        WHERE inventory_id = source_inventory_id
          AND part_num = part_to_transfer_num
          AND color_id = color_to_transfer_id
          AND is_spare = FALSE
        FOR UPDATE;
        SELECT COALESCE(quantity, 0) INTO spare_quantity
        FROM lego_inventory_parts
        WHERE inventory_id = source_inventory_id
          AND part_num = part_to_transfer_num
          AND color_id = color_to_transfer_id
          AND is_spare = TRUE
        FOR UPDATE;
        PERFORM 1 FROM lego_inventory_parts
        WHERE inventory_id = target_inventory_id
          AND part_num = part_to_transfer_num
          AND color_id = color_to_transfer_id
        FOR UPDATE;
        IF regular_quantity + spare_quantity < quantity_to_transfer THEN
            error_msg := 'Insufficient quantity in source inventory (including spares).';
            log_status := 'failed';
            RAISE EXCEPTION '%', error_msg;
        END IF;
        DECLARE
            remaining_to_transfer INTEGER := quantity_to_transfer;
        BEGIN
            IF regular_quantity > 0 THEN
                IF regular_quantity >= remaining_to_transfer THEN
                    UPDATE lego_inventory_parts
                    SET quantity = quantity - remaining_to_transfer
                    WHERE inventory_id = source_inventory_id
                      AND part_num = part_to_transfer_num
                      AND color_id = color_to_transfer_id
                      AND is_spare = FALSE;
                    remaining_to_transfer := 0;
                ELSE
                    DELETE FROM lego_inventory_parts
                    WHERE inventory_id = source_inventory_id
                      AND part_num = part_to_transfer_num
                      AND color_id = color_to_transfer_id
                      AND is_spare = FALSE;
                    remaining_to_transfer := remaining_to_transfer - regular_quantity;
                END IF;
            END IF;
            IF remaining_to_transfer > 0 THEN
                IF spare_quantity >= remaining_to_transfer THEN
                    UPDATE lego_inventory_parts
                    SET quantity = quantity - remaining_to_transfer
                    WHERE inventory_id = source_inventory_id
                      AND part_num = part_to_transfer_num
                      AND color_id = color_to_transfer_id
                      AND is_spare = TRUE;
                    remaining_to_transfer := 0;
                ELSE
                    DELETE FROM lego_inventory_parts
                    WHERE inventory_id = source_inventory_id
                      AND part_num = part_to_transfer_num
                      AND color_id = color_to_transfer_id
                      AND is_spare = TRUE;
                    remaining_to_transfer := remaining_to_transfer - spare_quantity;
                END IF;
            END IF;
            DELETE FROM lego_inventory_parts
            WHERE inventory_id = source_inventory_id
              AND part_num = part_to_transfer_num
              AND color_id = color_to_transfer_id
              AND quantity = 0;
        END;
        DECLARE
            target_regular_quantity INTEGER;
        BEGIN
            SELECT quantity INTO target_regular_quantity
            FROM lego_inventory_parts
            WHERE inventory_id = target_inventory_id
              AND part_num = part_to_transfer_num
              AND color_id = color_to_transfer_id
              AND is_spare = FALSE;
            IF target_regular_quantity IS NOT NULL THEN
                UPDATE lego_inventory_parts
                SET quantity = quantity + quantity_to_transfer
                WHERE inventory_id = target_inventory_id
                  AND part_num = part_to_transfer_num
                  AND color_id = color_to_transfer_id
                  AND is_spare = FALSE;
            ELSE
                INSERT INTO lego_inventory_parts (
                    inventory_id, part_num, color_id, quantity, is_spare
                ) VALUES (
                    target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, FALSE
                );
            END IF;
        END;
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'success', NULL
        );
        RETURN format('Successfully transferred %s parts (%s, color_id: %s) from inventory %s to inventory %s. Reason: %s',
                      quantity_to_transfer, part_to_transfer_num, color_to_transfer_id, source_inventory_id, target_inventory_id, transfer_reason);
    EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS error_msg = MESSAGE_TEXT;
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', error_msg
        );
        RETURN 'Failed: ' || error_msg;
    END;
END;
$$;"}
